-- L3 Staging contract rehearsal. All fixtures and temporary role changes roll back.
begin;
select set_config('request.jwt.claim.sub',(select auth_user_id::text from public.employees where id='9f44daf9-9f87-4129-bc71-55c082cf8782'),true);
do $$
declare actor uuid:=marketing_private.actor();org uuid;brand uuid;other_brand uuid;role uuid;old_role uuid;old_profile_role uuid;uid uuid:=auth.uid();
 task jsonb;tpl jsonb;result jsonb;duplicate jsonb;request uuid:=gen_random_uuid();v_content_id uuid;date_key date:='2026-10-01';denied boolean;rev integer;cnt integer;
begin
 insert into public.organizations(name) values('Disposable Planner Contract Rehearsal') returning id into org;
 insert into public.organization_memberships values(org,actor);
 insert into public.brands(organization_id,name) values(org,'Disposable Planner Brand') returning id into brand;
 insert into public.brands(organization_id,name) values(org,'Disposable Other Brand') returning id into other_brand;
 perform public.marketing_planner_command(gen_random_uuid(),org,null,'open_month',null,0,jsonb_build_object('month',date_key));
 task:=public.marketing_planner_command(request,org,brand,'create',null,0,jsonb_build_object('month',date_key,'title','Disposable production task','content_type','post','due_date','2026-10-12','brief','Contract brief'));
 duplicate:=public.marketing_planner_command(request,org,brand,'create',null,0,jsonb_build_object('month',date_key,'title','Disposable production task','content_type','post','due_date','2026-10-12','brief','Contract brief'));
 if task->>'id'<>duplicate->>'id' then raise exception 'Request retry duplicated task';end if;
 denied:=false;begin perform public.marketing_planner_command(request,org,brand,'create',null,0,'{"title":"Changed retry"}');exception when others then denied:=true;end;if not denied then raise exception 'Changed request accepted';end if;
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,other_brand,'save',(task->>'id')::uuid,1,'{"title":"Cross-brand write"}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Cross-brand write accepted';end if;
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,brand,'transition',(task->>'id')::uuid,1,'{"status":"completed"}');exception when others then denied:=true;end;if not denied then raise exception 'Completion bypass accepted';end if;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'transition',(task->>'id')::uuid,1,'{"status":"in_progress"}');
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'save',(task->>'id')::uuid,(task->>'revision')::integer,'{"blocked":true,"blocker_reason":"Awaiting reference"}');
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,brand,'transition',(task->>'id')::uuid,(task->>'revision')::integer,'{"status":"in_review"}');exception when others then denied:=true;end;if not denied then raise exception 'Blocked work entered review';end if;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'save',(task->>'id')::uuid,(task->>'revision')::integer,'{"blocked":false}');
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'transition',(task->>'id')::uuid,(task->>'revision')::integer,'{"status":"in_review"}');
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,brand,'request_revision',(task->>'id')::uuid,(task->>'revision')::integer,'{}');exception when others then denied:=true;end;if not denied then raise exception 'Empty revision feedback accepted';end if;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'request_revision',(task->>'id')::uuid,(task->>'revision')::integer,'{"feedback":"Use the approved visual"}');
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'transition',(task->>'id')::uuid,(task->>'revision')::integer,'{"status":"in_review"}');
 -- Exact canonical authorizer with a disposable non-reviewer role; reset before continuing.
 select role_id into old_role from public.employees where id=actor;select role_id into old_profile_role from public.user_profiles where id=uid;
 insert into public.roles(name) values('Disposable Planner Creator') returning id into role;
 insert into public.role_permissions(role_id,permission_id) select role,id from public.permissions where code in ('marketing_workspace.access','marketing_planner.view','marketing_planner.create','marketing_planner.edit');
 update public.platform_member_brand_scopes set all_brands=false where organization_id=org and employee_id=actor;
 insert into public.platform_member_brands values(org,actor,brand);
 update public.employees set role_id=role where id=actor;update public.user_profiles set role_id=role where id=uid;
 denied:=false;begin perform public.marketing_planner_read(org,date_key,other_brand);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Selected brand scope leaked';end if;
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,brand,'approve',(task->>'id')::uuid,(task->>'revision')::integer,'{}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Creator without reviewer grant approved';end if;
 if not exists(select 1 from jsonb_array_elements(public.marketing_planner_read(org,date_key,brand)->'tasks') x where x->>'id'=task->>'id') then raise exception 'Scoped creator read unavailable';end if;
 update public.employees set role_id=old_role where id=actor;update public.user_profiles set role_id=old_profile_role where id=uid;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'approve',(task->>'id')::uuid,(task->>'revision')::integer,'{"feedback":"Approved production only"}');
 if task->>'status'<>'completed' or task->>'approved_revision'<>task->>'revision' then raise exception 'Approval revision not bound';end if;
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'handoff',(task->>'id')::uuid,(task->>'revision')::integer,'{}');v_content_id:=(result->>'content_id')::uuid;
 select revision into rev from public.marketing_creative_tasks where id=(task->>'id')::uuid;
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'handoff',(task->>'id')::uuid,rev,'{}');
 if (result->>'content_id')::uuid<>v_content_id or (select status from public.marketing_content where id=v_content_id)<>'draft' then raise exception 'Handoff duplicated or approved publication';end if;
 if (select payload->>'creative_brief' from public.marketing_content_revisions where content_id=v_content_id and revision=1)<>'Contract brief' then raise exception 'Brief not transferred';end if;
 perform public.marketing_planner_order(gen_random_uuid(),org,date_key,jsonb_build_array(jsonb_build_object('id',task->>'id','revision',rev)));
 select revision into rev from public.marketing_creative_tasks where id=(task->>'id')::uuid;
 if (select approved_revision from public.marketing_creative_tasks where id=(task->>'id')::uuid)<>rev then raise exception 'Manual ordering invalidated creative approval';end if;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'save',(task->>'id')::uuid,rev,'{"title":"Changed after approval"}');
 if task->>'status'<>'in_progress' or task->>'approved_revision' is not null then raise exception 'Edit retained stale production approval';end if;
 denied:=false;begin perform public.marketing_planner_command(gen_random_uuid(),org,brand,'save',(task->>'id')::uuid,1,'{"title":"Stale writer"}');exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Stale revision accepted';end if;
 task:=public.marketing_planner_command(gen_random_uuid(),org,brand,'save',(task->>'id')::uuid,(task->>'revision')::integer,'{"planned_week":"2026-10-19"}');
 if task->>'due_date'<>'2026-10-12' then raise exception 'Week planning silently changed deadline';end if;
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'target',null,0,'{"month":"2026-10-01","mode":"default","posts":8,"reels":4}');
 if (select posts from public.marketing_creative_month_targets where brand_id=brand and month=date_key)<>0 then raise exception 'Default changed existing month';end if;
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'open_month',null,0,'{"month":"2026-11-01"}');
 if (select posts from public.marketing_creative_month_targets where brand_id=brand and month='2026-11-01')<>8 then raise exception 'New month did not apply defaults';end if;
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'target',null,1,'{"month":"2026-11-01","mode":"month","posts":6,"reels":2}');
 if (select posts from public.marketing_creative_target_defaults where brand_id=brand)<>8 then raise exception 'Month override changed default';end if;
 tpl:=public.marketing_planner_command(gen_random_uuid(),org,brand,'template',null,0,'{"month":"2026-10-01","title":"Weekly image","content_type":"post","frequency":"weekly","day":1}');
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'skip_occurrence',(tpl->>'id')::uuid,0,'{"month":"2026-10-01","date":"2026-10-05"}');
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'generate',null,0,'{"month":"2026-10-01"}');
 if (result->>'generated')::integer<>3 then raise exception 'Recurring count or skip incorrect %',result;end if;
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'generate',null,0,'{"month":"2026-10-01"}');if (result->>'generated')::integer<>0 then raise exception 'Duplicate recurring generation';end if;
 select to_jsonb(t) into task from public.marketing_creative_tasks t where t.brand_id=brand and title='Weekly image' limit 1;
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'delete',(task->>'id')::uuid,(task->>'revision')::integer,'{}');
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'generate',null,0,'{"month":"2026-10-01"}');if (result->>'generated')::integer<>0 then raise exception 'Removed recurring occurrence regenerated';end if;
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'template',(tpl->>'id')::uuid,1,'{"month":"2026-10-01","title":"Changed template","content_type":"post","frequency":"weekly","day":1}');
 perform public.marketing_planner_command(gen_random_uuid(),org,brand,'template',(tpl->>'id')::uuid,2,'{"month":"2026-10-01","title":"Changed template","content_type":"post","frequency":"weekly","day":2}');
 result:=public.marketing_planner_command(gen_random_uuid(),org,brand,'generate',null,0,'{"month":"2026-10-01"}');if (result->>'generated')::integer<>0 then raise exception 'Day change duplicated existing weekly occurrences';end if;
 if exists(select 1 from public.marketing_creative_tasks where brand_id=brand and title='Changed template') then raise exception 'Template rewrote occurrences';end if;
 result:=public.marketing_planner_read(org,date_key,brand);
 if jsonb_array_length(result->'tasks')<>3 then raise exception 'Read projection count incorrect %',jsonb_array_length(result->'tasks');end if;
 if has_table_privilege('authenticated','public.marketing_creative_tasks','INSERT') or has_function_privilege('anon','public.marketing_planner_command(uuid,uuid,uuid,text,uuid,integer,jsonb)','EXECUTE') then raise exception 'Direct authority exposed';end if;
 raise notice 'PASS: scope, permissions, lifecycle, revision invalidation, review, recurrence, targets and idempotent draft handoff';
end $$;
rollback;
